"use client";
import React, { useEffect, useState } from "react";
import Map, { ViewStateChangeEvent } from "react-map-gl";
import { motion, AnimatePresence } from "framer-motion";

import WeatherCard from "@/components/WeatherCard";
import GeocoderControl from "@/components/geocoder-control";
import { getWeather } from "./actions";
import ArrowComponent from "@/components/ArrowComponent";

const mapboxAPIKey = process.env.NEXT_PUBLIC_MAPBOX_API_KEY as string;

interface Place {
  longitude: number;
  latitude: number;
  zoom: number;
  query: string;
}

interface WeatherData {
  location: {
    name: string;
    country: string;
    localtime: string; // Assuming this is a date/time string
  };
  current: {
    temperature: number;
    feelslike: number;
    weather_descriptions: string[];
    wind_speed: number;
    wind_dir: string;
    humidity: number;
    uv_index: number;
    visibility: number;
  };
}

export default function App() {
  // default location
  const [place, setPlace] = useState<Place>({
    longitude: -122.4194,
    latitude: 37.7749,
    zoom: 12,
    query: "San Francisco, CA",
  });

  const [weatherData, setWeatherData] = useState<WeatherData | null>(null);

  // fetching current location of user
  useEffect(() => {
    let isMounted = true;
    const ipStackAPIKey = process.env.NEXT_PUBLIC_IPSTACK_API_KEY;

    const fetchUserLocation = async () => {
      try {
        const getIp = await fetch(
          `http://api.ipstack.com/check?access_key=${ipStackAPIKey}`
        );
        const data = await getIp.json();

        if (!isMounted) return;

        const position = {
          longitude: data.longitude,
          latitude: data.latitude,
          zoom: 12,
          query: data.region_name,
        };
        setPlace(position);
      } catch (error) {
        console.error("Error fetching user location:", error);
      }
    };

    fetchUserLocation();

    return () => {
      isMounted = false;
    };
  }, []);

  // fetching weather of newly entered region
  useEffect(() => {
    const fetchWeather = async () => {
      setIsVisible(false);

      if (place.query !== "San Francisco, CA") {
        try {
          const data = await getWeather(place.query);
          setWeatherData(data);
          console.log("Weather data:", data);

          const input = document.querySelector(
            ".mapboxgl-ctrl-geocoder--input"
          ) as HTMLInputElement;
          if (input) {
            input.value = data.location.name;
          }
        } catch (error) {
          console.error("Error fetching weather data:", error);
        }
      }
    };

    fetchWeather();
  }, [place.query]);

  const handleMove = (evt: ViewStateChangeEvent) => {
    setPlace((prev) => ({
      ...prev,
      longitude: evt.viewState.longitude,
      latitude: evt.viewState.latitude,
      zoom: evt.viewState.zoom,
    }));
  };

  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    setIsVisible(true);
  }, [weatherData]);

  return (
    <>
      <Map
        {...place}
        onMove={handleMove}
        mapStyle="mapbox://styles/mapbox/streets-v11"
        mapboxAccessToken={mapboxAPIKey}
      >
        <GeocoderControl
          mapboxAccessToken={mapboxAPIKey}
          setPlace={setPlace}
          position="top-left"
        />
      </Map>
      <AnimatePresence>
        {isVisible && (
          <motion.div
            key="weather-card"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 0.5 }} // Adjust duration as needed
          >
            {weatherData && <WeatherCard data={weatherData} />}
          </motion.div>
        )}
      </AnimatePresence>
      <ArrowComponent />
    </>
  );
}

import * as React from "react";
import { useState } from "react";
import { useControl, Marker, MarkerProps, ControlPosition } from "react-map-gl";
import MapboxGeocoder, { GeocoderOptions } from "@mapbox/mapbox-gl-geocoder";

type GeocoderControlProps = Omit<
  GeocoderOptions,
  "accessToken" | "mapboxgl" | "marker"
> & {
  mapboxAccessToken: string;
  marker?: boolean | Omit<MarkerProps, "longitude" | "latitude">;
  position: ControlPosition;
  onLoading?: any;
  onResults?: any;
  onResult?: any;
  onError?: any;
  setPlace: (place: {
    query: string;
    longitude: number;
    latitude: number;
    zoom: number;
  }) => void;
};

const GeocoderControl: React.FC<GeocoderControlProps> = (props) => {
  const [marker, setMarker] = useState<React.ReactNode>(null);

  const geocoder = useControl<MapboxGeocoder>(
    () => {
      const ctrl = new MapboxGeocoder({
        ...props,
        marker: false,
        accessToken: props.mapboxAccessToken,
      });
      ctrl.on("loading", props.onLoading);
      ctrl.on("results", props.onResults);
      ctrl.on("result", (evt) => {
        props.onResult?.(evt);

        const { result } = evt;
        const location =
          result &&
          (result.center ||
            (result.geometry?.type === "Point" && result.geometry.coordinates));

        props.setPlace({
          query: result.text,
          longitude: location[0],
          latitude: location[1],
          zoom: 12,
        });

        if (location && props.marker) {
          setMarker(
            <Marker
              {...(props.marker as Omit<MarkerProps, "longitude" | "latitude">)}
              longitude={location[0]}
              latitude={location[1]}
            />
          );
        } else {
          setMarker(null);
        }
      });
      ctrl.on("error", props.onError);
      return ctrl;
    },
    {
      position: props.position,
    }
  );

  React.useEffect(() => {
    if (geocoder) {
      if (
        props.proximity !== undefined &&
        geocoder.getProximity() !== props.proximity
      ) {
        geocoder.setProximity(props.proximity);
      }
      if (
        props.render !== undefined &&
        geocoder.getRenderFunction() !== props.render
      ) {
        geocoder.setRenderFunction(props.render);
      }
      if (
        props.language !== undefined &&
        geocoder.getLanguage() !== props.language
      ) {
        geocoder.setLanguage(props.language);
      }
      if (props.zoom !== undefined && geocoder.getZoom() !== props.zoom) {
        geocoder.setZoom(props.zoom);
      }
      if (props.flyTo !== undefined && geocoder.getFlyTo() !== props.flyTo) {
        geocoder.setFlyTo(props.flyTo);
      }
      if (
        props.placeholder !== undefined &&
        geocoder.getPlaceholder() !== props.placeholder
      ) {
        geocoder.setPlaceholder(props.placeholder);
      }
      if (
        props.countries !== undefined &&
        geocoder.getCountries() !== props.countries
      ) {
        geocoder.setCountries(props.countries);
      }
      if (props.types !== undefined && geocoder.getTypes() !== props.types) {
        geocoder.setTypes(props.types);
      }
      if (
        props.minLength !== undefined &&
        geocoder.getMinLength() !== props.minLength
      ) {
        geocoder.setMinLength(props.minLength);
      }
      if (props.limit !== undefined && geocoder.getLimit() !== props.limit) {
        geocoder.setLimit(props.limit);
      }
      if (props.filter !== undefined && geocoder.getFilter() !== props.filter) {
        geocoder.setFilter(props.filter);
      }
      if (props.origin !== undefined && geocoder.getOrigin() !== props.origin) {
        geocoder.setOrigin(props.origin);
      }
    }
  }, [
    geocoder,
    props.proximity,
    props.render,
    props.language,
    props.zoom,
    props.flyTo,
    props.placeholder,
    props.countries,
    props.types,
    props.minLength,
    props.limit,
    props.filter,
    props.origin,
  ]);

  return <>{marker}</>;
};

const noop = () => {};

GeocoderControl.defaultProps = {
  marker: true,
  onLoading: noop,
  onResults: noop,
  onResult: noop,
  onError: noop,
};

export default GeocoderControl;

import React from "react";
import { format } from "timeago.js";
import {
  Droplet,
  Eye,
  Wind,
  Snow,
  SunLight,
  CloudSunny,
  Rain,
  Thunderstorm,
  HeavyRain,
  Fog,
} from "iconoir-react";

const WeatherIcon = ({
  temperature,
  description,
}: {
  temperature: number;
  description: string;
}) => {
  const iconSize = 48;
  const lowercaseDescription = description.toLowerCase();

  if (temperature <= 0 || lowercaseDescription.includes("snow")) {
    return (
      <Snow width={iconSize} height={iconSize} className="text-blue-300" />
    );
  } else if (
    lowercaseDescription.includes("rain") ||
    lowercaseDescription.includes("drizzle")
  ) {
    return (
      <Rain width={iconSize} height={iconSize} className="text-gray-400" />
    );
  } else if (
    lowercaseDescription.includes("storm") ||
    lowercaseDescription.includes("thunder")
  ) {
    return (
      <Thunderstorm
        width={iconSize}
        height={iconSize}
        className="text-yellow-500"
      />
    );
  } else if (lowercaseDescription.includes("cloud")) {
    return (
      <CloudSunny
        width={iconSize}
        height={iconSize}
        className="text-gray-500"
      />
    );
  } else if (lowercaseDescription.includes("clear") || temperature > 25) {
    return (
      <SunLight
        width={iconSize}
        height={iconSize}
        className="text-yellow-400"
      />
    );
  } else if (
    lowercaseDescription.includes("mist") ||
    lowercaseDescription.includes("fog")
  ) {
    return <Fog width={iconSize} height={iconSize} className="text-gray-400" />;
  } else if (lowercaseDescription.includes("heavy rain")) {
    return (
      <HeavyRain width={iconSize} height={iconSize} className="text-blue-600" />
    );
  } else {
    // Default icon for unknown conditions
    return (
      <CloudSunny
        width={iconSize}
        height={iconSize}
        className="text-gray-500"
      />
    );
  }
};

interface WeatherData {
  location: {
    name: string;
    country: string;
    localtime: string; // Assuming this is a date/time string
  };
  current: {
    temperature: number;
    feelslike: number;
    weather_descriptions: string[];
    wind_speed: number;
    wind_dir: string;
    humidity: number;
    uv_index: number;
    visibility: number;
  };
}

interface Props {
  data: WeatherData;
}

const WeatherCard: React.FC<Props> = ({ data }) => {
  const { location, current } = data;

  return (
    <div className="fixed md:top-[13px] md:right-[13px] bottom-0 md:bottom-auto w-full md:w-[400px] bg-white rounded-t-[10px] md:rounded-[10px] smooth-shadow overflow-hidden">
      {location ? (
        <>
          <div className="p-4 w-full">
            <div className="uppercase tracking-wide text-sm text-indigo-500 font-semibold">
              {location.name}, {location.country}
            </div>
            <div className="flex items-center mr-5">
              <div className="flex-1">
                <p className="block text-4xl font-bold mt-4 leading-tight text-black">
                  {current.temperature}°C
                </p>
                <p className="text-gray-500 text-sm my-1">
                  Feels like {current.feelslike}°C
                </p>
                <p className="text-gray-500 text-sm my-1">
                  {current.weather_descriptions[0]},{" "}
                  {format(location.localtime)}
                </p>
              </div>
              <WeatherIcon
                temperature={current.temperature}
                description={current.weather_descriptions[0]}
              />
            </div>
          </div>
          <div className="mt-3 grid grid-cols-2 bg-[#F3F3F3]">
            <div className="flex items-center p-3 border-r border-t border-b mt-[-1px] border-gray-300">
              <Wind className="h-5 w-5 text-gray-500 mr-2" strokeWidth={1.8} />
              <p className="text-sm font-medium text-gray-800">
                {current.wind_speed} m/s {current.wind_dir}
              </p>
            </div>
            <div className="flex items-center p-3 border-r border-t border-b mt-[-1px] border-gray-300">
              <Droplet
                className="h-5 w-5 text-gray-500 mr-2 border-b"
                strokeWidth={1.8}
              />
              <p className="text-sm font-medium text-gray-800">
                {current.humidity}% humidity
              </p>
            </div>
            <div className="flex items-center p-3 border-r border-t border-b mt-[-1px] border-gray-300">
              <SunLight
                className="h-5 w-5 text-gray-500 mr-2"
                strokeWidth={1.8}
              />
              <p className="text-sm font-medium text-gray-800">
                UV Index: {current.uv_index}
              </p>
            </div>
            <div className="flex items-center p-3 border-r border-t border-b mt-[-1px] border-gray-300">
              <Eye className="h-5 w-5 text-gray-500 mr-2" strokeWidth={1.8} />
              <p className="text-sm font-medium text-gray-800">
                {current.visibility} km visibility
              </p>
            </div>
          </div>
        </>
      ) : (
        <div className="p-4 w-full">
          <div className="uppercase tracking-wide text-sm leading-[180%] text-zinc-600 font-semibold">
            No weather information available for this region, try searching some
            other place.
          </div>
        </div>
      )}
    </div>
  );
};

export default WeatherCard;

